def _direction(a, b) -> int:
    """+1 if a>b, -1 if a<b, 0 if equal (neutral)."""
    if a > b:
        return 1
    if a < b:
        return -1
    return 0


def _score_from_directions(dirs) -> float:
    """Map a list of +1/-1/0 votes to a 0-100 score centred at 50."""
    if not dirs:
        return 50.0
    avg = sum(dirs) / len(dirs)  # in [-1, 1]
    return _clamp(50.0 + avg * 50.0)


def _score_ma(close, short, long_) -> float:
    """Trend score from a short/long moving-average pair vs price.

    Bullish when price is above the averages and the short leads the long;
    price sitting exactly on an average is treated as neutral, not bearish.
    """
    if close is None or short is None or long_ is None:
        return 50.0
    dirs = [_direction(close, short), _direction(close, long_),
            _direction(short, long_)]
    return _score_from_directions(dirs)

