"""app.py - Flask dashboard for the personal stock signal tool.

Renders weighted BUY/HOLD/SELL signals for the active quick list, allows
drilling into a full sector on demand, and shows a simulated backtest per
ticker.

SAFETY / SCOPE
--------------
Research and learning only. This app displays signals derived from public
market data. It NEVER places trades and NEVER connects to a broker. The
built-in Flask server is a local, unauthenticated dev server - do not expose
it to a network as-is.
"""

from __future__ import annotations

from flask import Flask, abort, render_template

import analysis
import backtester
import config
import data_fetcher

DISCLAIMER = (
    "Research and learning only. Signals are informational, not financial "
    "advice. This tool never places trades or connects to a broker."
)


def _sector_for(ticker: str) -> str:
    for sector, tickers in config.WATCHLIST.items():
        if ticker in tickers:
            return sector
    return "unknown"


def build_signals(tickers: list[str]) -> list[dict]:
    """Fetch prices for `tickers` and return a list of signal rows."""
    prices = data_fetcher.get_price_history_batch(tickers)
    rows = []
    for ticker in tickers:
        frame = prices.get(ticker)
        result = analysis.analyze(frame) if frame is not None else {
            "score": None, "label": "N/A", "breakdown": {}, "indicators": {}}
        indicators = result.get("indicators") or {}
        rows.append({
            "ticker": ticker,
            "sector": _sector_for(ticker),
            "label": result["label"],
            "score": result["score"],
            "close": indicators.get("Close"),
            "rsi": indicators.get("RSI"),
            "breakdown": result.get("breakdown", {}),
        })
    return rows


def create_app() -> Flask:
    app = Flask(__name__)

    @app.context_processor
    def inject_globals():
        return {"disclaimer": DISCLAIMER, "sectors": list(config.WATCHLIST.keys())}

    @app.route("/")
    def index():
        signals = build_signals(config.QUICK_LIST)
        return render_template(
            "index.html",
            title="Quick List Signals",
            signals=signals,
            quick_list=config.QUICK_LIST,
        )

    @app.route("/sector/<sector>")
    def sector_view(sector):
        tickers = config.WATCHLIST.get(sector)
        if not tickers:
            abort(404)
        signals = build_signals(tickers)
        return render_template(
            "sector.html",
            title=f"Sector: {sector}",
            sector=sector,
            signals=signals,
        )

    @app.route("/backtest/<ticker>")
    def backtest_view(ticker):
        ticker = ticker.upper()
        all_tickers = [t for group in config.WATCHLIST.values() for t in group]
        if ticker not in all_tickers:
            abort(404)
        frame = data_fetcher.get_price_history(ticker)
        stats = backtester.backtest(frame)
        current = analysis.analyze(frame)
        return render_template(
            "backtest.html",
            title=f"Backtest: {ticker}",
            ticker=ticker,
            stats=stats,
            current=current,
            has_data=frame is not None and len(frame) > 0,
        )

    return app


app = create_app()


if __name__ == "__main__":
    # Local, unauthenticated dev server - do not expose to a network.
    app.run(host="127.0.0.1", port=5000, debug=True)

{% extends "base.html" %}
{% from "_signals_table.html" import signals_table %}

{% block content %}
  <p class="lead">
    Active quick list ({{ quick_list|join(', ') }}) - a small set kept short to
    avoid hammering the data provider on the first run.
  </p>

  {{ signals_table(signals) }}

  <p class="hint">
    Signal is a weighted blend of MACD, moving averages, RSI, and Bollinger
    Bands on a 0-100 scale (BUY &ge; {{ 65 }}, SELL &le; {{ 35 }}).
    Browse a full sector using the navigation above.
  </p>
{% endblock %}

{% extends "base.html" %}
{% from "_signals_table.html" import signals_table %}

{% block content %}
  <p class="lead">Signals for every ticker in the <strong>{{ sector }}</strong> sector.</p>
  {{ signals_table(signals) }}
  <p><a href="{{ url_for('index') }}">&larr; Back to quick list</a></p>
{% endblock %}

:root {
  --bg: #0f1420;
  --panel: #182030;
  --text: #e6e9ef;
  --muted: #9aa4b2;
  --buy: #1f9d55;
  --sell: #c0392b;
  --hold: #b7791f;
  --border: #263041;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.site-header {
  padding: 1rem 1.5rem;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
}
.site-header h1 { margin: 0 0 .5rem; font-size: 1.3rem; }
.site-header h1 a { color: var(--text); text-decoration: none; }
.site-header nav a {
  color: var(--muted);
  margin-right: .9rem;
  text-decoration: none;
  text-transform: capitalize;
  font-size: .9rem;
}
.site-header nav a:hover { color: var(--text); }

.disclaimer {
  background: #2a2410;
  color: #f0d98a;
  padding: .6rem 1.5rem;
  font-size: .85rem;
  border-bottom: 1px solid var(--border);
}

main { padding: 1.5rem; max-width: 960px; margin: 0 auto; }
.lead { color: var(--muted); }
.hint, .warn { font-size: .85rem; color: var(--muted); }
.warn { color: #f0b36b; }

table.signals, table.stats {
  width: 100%;
  border-collapse: collapse;
  margin: 1rem 0;
  background: var(--panel);
  border: 1px solid var(--border);
}
table.signals th, table.signals td,
table.stats th, table.stats td {
  padding: .55rem .7rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
table.signals thead th { color: var(--muted); font-weight: 600; font-size: .85rem; }
.ticker { font-weight: 700; }

.badge {
  display: inline-block;
  padding: .15rem .55rem;
  border-radius: 999px;
  font-size: .78rem;
  font-weight: 700;
  color: #fff;
}
.badge-buy { background: var(--buy); }
.badge-sell { background: var(--sell); }
.badge-hold { background: var(--hold); }
.badge-n\/a { background: #555; }

.site-footer {
  padding: 1rem 1.5rem;
  color: var(--muted);
  font-size: .8rem;
  border-top: 1px solid var(--border);
}
