/* ==========================================================================
   Stock Signal Dashboard - dark "trading desk" theme
   All colors are CSS variables so the palette stays consistent.
   ========================================================================== */
:root {
  /* Surfaces */
  --bg: #0b0e14;
  --bg-elev: #10151f;
  --panel: #151c28;
  --panel-2: #1a2333;
  --border: #232d40;
  --border-soft: #1b2431;

  /* Text */
  --text: #e7ebf3;
  --muted: #8b97ab;
  --muted-2: #5e6a7e;

  /* Brand / accent */
  --accent: #3b82f6;
  --accent-2: #60a5fa;

  /* Signals: green buy, red sell, yellow hold */
  --buy: #16c784;
  --buy-bg: rgba(22, 199, 132, 0.14);
  --sell: #ea3943;
  --sell-bg: rgba(234, 57, 67, 0.14);
  --hold: #f5a623;
  --hold-bg: rgba(245, 166, 35, 0.14);
  --na: #6b7686;
  --na-bg: rgba(107, 118, 134, 0.14);

  /* Effects */
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  --shadow-hover: 0 12px 32px rgba(0, 0, 0, 0.5);
  --mono: "SF Mono", "JetBrains Mono", "Consolas", ui-monospace, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  font-family: var(--sans);
  background:
    radial-gradient(1200px 600px at 80% -10%, rgba(59, 130, 246, 0.08), transparent 60%),
    var(--bg);
  color: var(--text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 { margin: 0; font-weight: 650; letter-spacing: -0.01em; }
.muted { color: var(--muted); font-weight: 400; }

/* ------------------------------------------------------------------ header */
.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.85rem 1.5rem;
  background: rgba(16, 21, 31, 0.85);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: 0.65rem; }
.brand h1 { font-size: 1.15rem; }
.logo-dot {
  width: 12px; height: 12px; border-radius: 50%;
  background: var(--buy);
  box-shadow: 0 0 0 4px var(--buy-bg), 0 0 12px var(--buy);
}
.topbar-actions { display: flex; align-items: center; gap: 1rem; }
.last-updated { color: var(--muted); font-size: 0.82rem; }
.last-updated time { color: var(--text); font-family: var(--mono); }

/* buttons */
.btn {
  display: inline-flex; align-items: center; gap: 0.4rem;
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.5rem 0.9rem;
  font-size: 0.85rem;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}
.btn:hover { background: #24304a; border-color: #33415c; }
.btn:active { transform: translateY(1px); }
.btn.ghost { background: transparent; border-color: transparent; font-size: 1.1rem; padding: 0.25rem 0.5rem; }
.btn.ghost:hover { background: var(--panel-2); }
.btn-icon { font-size: 1rem; line-height: 1; }

/* -------------------------------------------------------------------- tabs */
.tabs {
  display: flex;
  gap: 0.25rem;
  padding: 0.75rem 1.5rem 0;
  overflow-x: auto;
  border-bottom: 1px solid var(--border-soft);
}
.tab {
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--muted);
  padding: 0.55rem 0.85rem;
  font-size: 0.9rem;
  text-transform: capitalize;
  cursor: pointer;
  white-space: nowrap;
  transition: color 0.15s, border-color 0.15s;
}
.tab:hover { color: var(--text); }
.tab.active { color: var(--text); border-bottom-color: var(--accent); }

/* -------------------------------------------------------------------- main */
main { max-width: 1180px; margin: 0 auto; padding: 1.5rem; }
.status { color: var(--muted); font-size: 0.85rem; min-height: 1.2rem; }

/* --------------------------------------------------------------- card grid */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 1rem;
  margin-top: 0.5rem;
}
.card {
  position: relative;
  background: linear-gradient(180deg, var(--panel), var(--bg-elev));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1.1rem;
  cursor: pointer;
  transition: transform 0.12s, border-color 0.15s, box-shadow 0.15s;
  overflow: hidden;
}
.card::before {
  content: "";
  position: absolute; left: 0; top: 0; bottom: 0; width: 3px;
  background: var(--sig, var(--na));
}
.card:hover { transform: translateY(-3px); border-color: #34415d; box-shadow: var(--shadow-hover); }
.card.selected { border-color: var(--accent); }

.card-top { display: flex; align-items: baseline; justify-content: space-between; }
.card-ticker { font-size: 1.15rem; font-weight: 700; letter-spacing: 0.01em; }
.card-sector { font-size: 0.72rem; color: var(--muted); text-transform: capitalize; }
.card-mid { display: flex; align-items: center; justify-content: space-between; margin: 0.9rem 0 0.6rem; }
.card-score { font-family: var(--mono); font-size: 1.7rem; font-weight: 700; }
.card-price { text-align: right; }
.card-price .lbl { display: block; font-size: 0.68rem; color: var(--muted); }
.card-price .val { font-family: var(--mono); font-size: 0.95rem; }

/* confidence meter */
.meter { height: 5px; background: var(--panel-2); border-radius: 99px; overflow: hidden; }
.meter > span { display: block; height: 100%; background: var(--sig, var(--accent)); border-radius: 99px; }
.card-conf { font-size: 0.7rem; color: var(--muted); margin-top: 0.35rem; }

/* ----------------------------------------------------------------- badges */
.badge {
  display: inline-flex; align-items: center;
  padding: 0.2rem 0.6rem;
  border-radius: 99px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--na); background: var(--na-bg);
}
.badge-buy { color: var(--buy); background: var(--buy-bg); }
.badge-sell { color: var(--sell); background: var(--sell-bg); }
.badge-hold { color: var(--hold); background: var(--hold-bg); }
.badge-na { color: var(--na); background: var(--na-bg); }

/* score text coloring */
.pos { color: var(--buy); }
.neg { color: var(--sell); }
.flat { color: var(--muted); }

/* ------------------------------------------------------------------ detail */
.detail {
  margin-top: 1.75rem;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.detail-head {
  display: flex; align-items: center; gap: 1rem;
  padding: 1.1rem 1.3rem;
  border-bottom: 1px solid var(--border-soft);
  background: linear-gradient(180deg, var(--panel-2), transparent);
}
.detail-id h2 { font-size: 1.5rem; font-family: var(--mono); }
.detail-signal { display: flex; align-items: center; gap: 0.7rem; margin-left: auto; }
.detail-score { font-family: var(--mono); font-size: 1.25rem; font-weight: 700; }

/* timeframe switcher (segmented control) */
.timeframe {
  display: inline-flex;
  gap: 2px;
  margin: 1rem 1.3rem 0;
  padding: 3px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
}
.tf-btn {
  background: none; border: none; color: var(--muted);
  padding: 0.35rem 0.8rem; border-radius: 6px;
  font-size: 0.8rem; font-family: var(--mono); cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.tf-btn:hover { color: var(--text); }
.tf-btn.active { background: var(--accent); color: #fff; }

.detail-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 1rem;
  padding: 1.2rem 1.3rem 1.4rem;
}
.panel {
  background: var(--panel);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  padding: 1rem 1.1rem;
}
.panel h3 { font-size: 0.95rem; margin-bottom: 0.6rem; }
.panel-hint { font-size: 0.75rem; color: var(--muted); margin: -0.3rem 0 0.6rem; }
.chart-panel { grid-row: span 2; }
.chart-wrap { position: relative; width: 100%; }
.backtest-panel { grid-column: 1 / -1; }

/* key/value + breakdown tables */
table.kv { width: 100%; border-collapse: collapse; font-size: 0.85rem; }
table.kv th { text-align: left; color: var(--muted); font-weight: 600; font-size: 0.75rem; padding-bottom: 0.4rem; }
table.kv td { padding: 0.32rem 0; border-top: 1px solid var(--border-soft); font-variant-numeric: tabular-nums; }
table.kv td:first-child { color: var(--muted); }
table.kv td.num, table.kv th.num { text-align: right; font-family: var(--mono); }

/* backtest results */
.bt-summary { display: flex; flex-wrap: wrap; gap: 0.6rem 1.5rem; margin-bottom: 0.8rem; }
.bt-metric { display: flex; flex-direction: column; }
.bt-metric .lbl { font-size: 0.7rem; color: var(--muted); }
.bt-metric .val { font-family: var(--mono); font-size: 1.05rem; font-weight: 650; }
.bt-verdict { display: inline-flex; align-items: center; padding: 0.2rem 0.6rem; border-radius: 99px; font-size: 0.72rem; font-weight: 700; }
.bt-verdict.win { color: var(--buy); background: var(--buy-bg); }
.bt-verdict.lose { color: var(--sell); background: var(--sell-bg); }
.bt-note { font-size: 0.75rem; color: var(--muted-2); margin-top: 0.6rem; font-style: italic; }
.bt-message { color: var(--hold); font-size: 0.85rem; }

/* ------------------------------------------------------------------ footer */
.footer {
  max-width: 1180px; margin: 1rem auto 2rem;
  padding: 1rem 1.5rem;
  color: var(--muted-2);
  font-size: 0.78rem;
  border-top: 1px solid var(--border-soft);
}

/* responsive */
@media (max-width: 820px) {
  .detail-grid { grid-template-columns: 1fr; }
  .chart-panel { grid-row: auto; }
}

"use strict";

// Client for the dashboard API (same-origin). Plain JS, no framework.
const API = {
  watchlist: "/api/watchlist",
  signals: "/api/signals",
  ticker: (t, p) => `/api/ticker/${encodeURIComponent(t)}?period=${encodeURIComponent(p)}`,
  backtest: (t) => `/api/backtest/${encodeURIComponent(t)}`,
};

const state = {
  quickList: [],
  sectors: [],
  watchlist: {},
  signals: [],
  activeTab: "Quick List",
  ticker: null,
  period: window.DEFAULT_PERIOD || "6mo",
};

let priceChart = null;

// ---- formatting helpers ----------------------------------------------------
const fmtScore = (x) => (x === null || x === undefined ? "-" : (x >= 0 ? "+" : "") + x.toFixed(2));
const fmtPct = (x) => (x === null || x === undefined ? "-" : Math.round(x * 100) + "%");
const fmtPctVal = (x) => (x === null || x === undefined ? "-" : (x >= 0 ? "+" : "") + Number(x).toFixed(2) + "%");
const fmtNum = (x, dp = 2) => (x === null || x === undefined ? "-" : Number(x).toFixed(dp));

function signClass(x) {
  if (x === null || x === undefined) return "flat";
  return x > 0 ? "pos" : (x < 0 ? "neg" : "flat");
}
function labelClass(label) {
  return "badge badge-" + String(label || "na").toLowerCase().replace("/", "");
}
function sigColor(label) {
  const l = String(label || "").toLowerCase();
  if (l === "buy") return "var(--buy)";
  if (l === "sell") return "var(--sell)";
  if (l === "hold") return "var(--hold)";
  return "var(--na)";
}
function fmtCap(x) {
  if (!x) return "-";
  const units = [[1e12, "T"], [1e9, "B"], [1e6, "M"]];
  for (const [size, suffix] of units) {
    if (x >= size) return "$" + (x / size).toFixed(2) + suffix;
  }
  return "$" + Number(x).toFixed(0);
}

async function getJSON(url) {
  const resp = await fetch(url);
  const data = await resp.json().catch(() => ({}));
  if (!resp.ok) throw new Error(data.error || `request failed (${resp.status})`);
  return data;
}

// ---- tabs ------------------------------------------------------------------
function renderTabs() {
  const nav = document.getElementById("tabs");
  nav.innerHTML = "";
  const tabs = ["Quick List", ...state.sectors];
  for (const name of tabs) {
    const btn = document.createElement("button");
    btn.className = "tab" + (name === state.activeTab ? " active" : "");
    btn.textContent = name;
    btn.addEventListener("click", () => {
      state.activeTab = name;
      renderTabs();
      renderCards();
    });
    nav.appendChild(btn);
  }
}

function tickersForActiveTab() {
  if (state.activeTab === "Quick List") return state.quickList;
  return state.watchlist[state.activeTab] || [];
}

// ---- cards -----------------------------------------------------------------
function renderCards() {
  const grid = document.getElementById("card-grid");
  grid.innerHTML = "";
  const wanted = new Set(tickersForActiveTab());
  const rows = state.signals.filter((r) => wanted.has(r.ticker));

  if (!rows.length) {
    grid.innerHTML = `<p class="muted">No signals to show.</p>`;
    return;
  }

  for (const row of rows) {
    const color = sigColor(row.label);
    const card = document.createElement("div");
    card.className = "card" + (row.ticker === state.ticker ? " selected" : "");
    card.style.setProperty("--sig", color);
    card.innerHTML = `
      <div class="card-top">
        <span class="card-ticker">${row.ticker}</span>
        <span class="${labelClass(row.label)}">${row.label}</span>
      </div>
      <div class="card-sector">${row.sector}</div>
      <div class="card-mid">
        <span class="card-score ${signClass(row.score)}">${fmtScore(row.score)}</span>
        <span class="card-price">
          <span class="lbl">Close</span>
          <span class="val">${fmtNum(row.close)}</span>
        </span>
      </div>
      <div class="meter"><span style="width:${Math.round((row.confidence || 0) * 100)}%"></span></div>
      <div class="card-conf">Confidence ${fmtPct(row.confidence)}</div>`;
    card.addEventListener("click", () => openDetail(row.ticker));
    grid.appendChild(card);
  }
}

// ---- signals load ----------------------------------------------------------
async function loadSignals() {
  const status = document.getElementById("signals-status");
  status.textContent = "Loading signals...";
  try {
    const data = await getJSON(API.signals);
    state.signals = data.signals || [];
    status.textContent = "";
    setLastUpdated();
    renderCards();
    if (state.ticker) loadDetail();  // refresh open detail too
  } catch (err) {
    status.textContent = "Could not load signals: " + err.message;
  }
}

function setLastUpdated() {
  const el = document.getElementById("last-updated");
  el.textContent = new Date().toLocaleTimeString();
}

// ---- detail panel ----------------------------------------------------------
function openDetail(ticker) {
  state.ticker = ticker;
  document.getElementById("detail").hidden = false;
  document.getElementById("detail-ticker").textContent = ticker;
  renderCards(); // update .selected highlight
  loadDetail();
  loadBacktest();
  document.getElementById("detail").scrollIntoView({ behavior: "smooth", block: "start" });
}

function closeDetail() {
  state.ticker = null;
  document.getElementById("detail").hidden = true;
  renderCards();
}

async function loadDetail() {
  if (!state.ticker) return;
  const status = document.getElementById("detail-status");
  status.textContent = `Loading ${state.ticker} (${state.period})...`;
  try {
    const data = await getJSON(API.ticker(state.ticker, state.period));
    status.textContent = "";
    renderSignalHead(data);
    renderBreakdown(data);
    renderFundamentals(data);
    renderChart(data);
  } catch (err) {
    status.textContent = "Could not load ticker: " + err.message;
  }
}

function renderSignalHead(data) {
  const badge = document.getElementById("detail-badge");
  badge.className = labelClass(data.label);
  badge.textContent = data.label;
  const score = document.getElementById("detail-score");
  score.className = "detail-score " + signClass(data.score);
  score.textContent = fmtScore(data.score);
  document.getElementById("detail-confidence").textContent = "conf " + fmtPct(data.confidence);
  const f = data.fundamentals || {};
  document.getElementById("detail-name").textContent = f.longName || f.shortName || data.sector || "";
}

function renderBreakdown(data) {
  const body = document.getElementById("breakdown-body");
  body.innerHTML = "";
  const weights = data.weights || {};
  for (const [name, val] of Object.entries(data.breakdown || {})) {
    const tr = document.createElement("tr");
    tr.innerHTML = `<td>${name}</td>
      <td class="num ${signClass(val)}">${fmtScore(val)}</td>
      <td class="num">${fmtNum(weights[name], 3)}</td>`;
    body.appendChild(tr);
  }
}

function renderFundamentals(data) {
  const f = data.fundamentals || {};
  const rows = [
    ["Sector", f.sector || data.sector || "-"],
    ["Industry", f.industry || "-"],
    ["P/E (trailing)", fmtNum(f.trailingPE)],
    ["P/E (forward)", fmtNum(f.forwardPE)],
    ["Earnings growth", f.earningsGrowth != null ? fmtPctVal(f.earningsGrowth * 100) : "-"],
    ["Market cap", fmtCap(f.marketCap)],
    ["Dividend yield", f.dividendYield != null ? fmtPctVal(f.dividendYield * 100) : "-"],
  ];
  const body = document.getElementById("fundamentals-body");
  body.innerHTML = rows.map(([k, v]) => `<tr><td>${k}</td><td class="num">${v}</td></tr>`).join("");
}

function renderChart(data) {
  const chart = data.chart || [];
  const labels = chart.map((p) => p.date);
  const pick = (key) => chart.map((p) => p[key]);
  const datasets = [
    { label: "Close", data: pick("close"), borderColor: "#60a5fa", borderWidth: 1.6, pointRadius: 0, tension: 0.12 },
    { label: "SMA 20", data: pick("sma_short"), borderColor: "#16c784", borderWidth: 1, pointRadius: 0 },
    { label: "SMA 50", data: pick("sma_long"), borderColor: "#f5a623", borderWidth: 1, pointRadius: 0 },
  ];
  const ctx = document.getElementById("price-chart");
  if (priceChart) priceChart.destroy();
  priceChart = new Chart(ctx, {
    type: "line",
    data: { labels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: "index", intersect: false },
      plugins: { legend: { labels: { color: "#8b97ab", boxWidth: 12 } } },
      scales: {
        x: { ticks: { color: "#5e6a7e", maxTicksLimit: 8 }, grid: { color: "#1b2431" } },
        y: { ticks: { color: "#5e6a7e" }, grid: { color: "#1b2431" } },
      },
    },
  });
}

// ---- backtest --------------------------------------------------------------
async function loadBacktest() {
  if (!state.ticker) return;
  const body = document.getElementById("backtest-body");
  body.innerHTML = `<p class="muted">Running simulated backtest...</p>`;
  try {
    const d = await getJSON(API.backtest(state.ticker));
    if (!d.ok) {
      body.innerHTML = `<p class="bt-message">${d.message || "Backtest unavailable."}</p>`;
      return;
    }
    const verdict = d.beat_buy_and_hold
      ? `<span class="bt-verdict win">Beat buy &amp; hold</span>`
      : `<span class="bt-verdict lose">Underperformed buy &amp; hold</span>`;
    body.innerHTML = `
      <div class="bt-summary">
        <div class="bt-metric"><span class="lbl">Strategy return</span>
          <span class="val ${signClass(d.total_return_pct)}">${fmtPctVal(d.total_return_pct)}</span></div>
        <div class="bt-metric"><span class="lbl">Buy &amp; hold</span>
          <span class="val ${signClass(d.buy_and_hold_return_pct)}">${fmtPctVal(d.buy_and_hold_return_pct)}</span></div>
        <div class="bt-metric"><span class="lbl">Trades</span><span class="val">${d.num_trades}</span></div>
        <div class="bt-metric"><span class="lbl">Win rate</span><span class="val">${fmtNum(d.win_rate_pct, 1)}%</span></div>
        <div class="bt-metric"><span class="lbl">Max drawdown</span>
          <span class="val neg">${fmtNum(d.max_drawdown_pct, 1)}%</span></div>
      </div>
      ${verdict}
      <p class="bt-note">${d.disclaimer || ""} Window ${d.start_date} to ${d.end_date} (${d.trading_days} trading days).</p>`;
  } catch (err) {
    body.innerHTML = `<p class="bt-message">Could not run backtest: ${err.message}</p>`;
  }
}

// ---- wiring ----------------------------------------------------------------
async function init() {
  document.getElementById("refresh").addEventListener("click", loadSignals);
  document.getElementById("detail-close").addEventListener("click", closeDetail);
  document.querySelectorAll("#timeframe .tf-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      state.period = btn.dataset.period;
      document.querySelectorAll("#timeframe .tf-btn")
        .forEach((b) => b.classList.toggle("active", b === btn));
      loadDetail();
    });
  });

  try {
    const wl = await getJSON(API.watchlist);
    state.quickList = wl.quick_list || [];
    state.sectors = wl.sectors || [];
    state.watchlist = wl.watchlist || {};
  } catch (err) {
    document.getElementById("signals-status").textContent =
      "Could not load watchlist: " + err.message;
  }
  renderTabs();
  await loadSignals();
}

document.addEventListener("DOMContentLoaded", init);

